-- =============================================================================
-- 開発用デモデータ（ローカル DB 専用の seed）
--
-- 元データ: 開発用 Supabase（nicchyo-development）から読み取った、架空の出店者・
-- 架空の店舗・市/丁目/場所の配置・設定値。実在の人物・連絡先は含まない。
-- 含めていないもの: 認証ユーザー、ログイン・招待・トークン系、ログ・集計、
-- 出店者本人の氏名（vendor_owner_profiles）、画像 URL（開発用ストレージ参照は空にした）。
--
-- 読み込み: `npx supabase db reset`（ローカルの DB を作り直すときだけ実行される）。
-- 安全装置: 認証ユーザーか出店者が既にある DB には読み込まない（本番・開発用 DB は
-- どちらも認証ユーザーがあるので、誤って流しても例外で止まる）。
-- マイグレーションが既に入れている行（市 nichiyo/mokuyo、丁目 1〜7、設定など）はそのまま残す（ON CONFLICT DO NOTHING）。
-- 既にある行は残し、無い行だけ seed の値が入る。
-- =============================================================================

DO $guard$
BEGIN
  IF EXISTS (SELECT 1 FROM auth.users) OR EXISTS (SELECT 1 FROM public.vendors) THEN
    RAISE EXCEPTION 'seed.sql refused: target database is not an empty local database';
  END IF;
END
$guard$;

-- マイグレーションが既に作る市（nichiyo / mokuyo）は slug で対応づける。ID は環境ごとに違うため。
CREATE TEMP TABLE seed_market_map (dev_id uuid PRIMARY KEY, local_id uuid NOT NULL);
SELECT v.dev_id, m.id FROM (VALUES
  ('a4a4a535-65bd-4b00-8678-9fe341ab5811'::uuid, 'nichiyo'),
  ('c6ad2adf-632c-4620-bec9-361aab04ad50'::uuid, 'mokuyo')
) AS v(dev_id, slug) JOIN public.markets m ON m.slug = v.slug;

