INSERT INTO public.ai_models SELECT * FROM json_populate_recordset(NULL::public.ai_models, $json$[{"id": "gpt-4o-mini", "label": "GPT-4o mini（現行）", "description": "長く使ってきた既定のモデル。速度・安定性ともに実績がある。ChatGPT と Azure では提供が終了しており、APIもいずれ終わる見込み。", "token_param": "max_tokens", "supports_temperature": true, "reasoning_efforts": [], "reasoning_headroom_tokens": 0, "price_input_per_mtok": 0.15, "price_output_per_mtok": 0.6, "is_selectable": true, "sort_order": 10, "provider": "openai", "created_at": "2026-09-10T08:11:16.821015+00:00", "updated_at": "2026-09-10T08:11:16.821015+00:00"}, {"id": "gpt-5.4-nano", "label": "GPT-5.4 nano（推奨）", "description": "会話向けの軽量モデル。2026-07 の比較で最速だった。相談・店舗チャット・意図抽出のような、速さが体験を決める場面向け。", "token_param": "max_completion_tokens", "supports_temperature": true, "reasoning_efforts": ["none", "low", "medium", "high", "xhigh"], "reasoning_headroom_tokens": 4000, "price_input_per_mtok": 0.2, "price_output_per_mtok": 1.25, "is_selectable": true, "sort_order": 20, "provider": "openai", "created_at": "2026-09-10T08:11:16.821015+00:00", "updated_at": "2026-09-30T13:29:25.251615+00:00"}, {"id": "gpt-5.4-mini", "label": "GPT-5.4 mini", "description": "nano より賢いが約4倍高く、体感で2倍遅い。回り方プランのように、実際に順序を考える必要がある場面向け。", "token_param": "max_completion_tokens", "supports_temperature": true, "reasoning_efforts": ["none", "low", "medium", "high", "xhigh"], "reasoning_headroom_tokens": 6000, "price_input_per_mtok": 0.75, "price_output_per_mtok": 4.5, "is_selectable": true, "sort_order": 30, "provider": "openai", "created_at": "2026-09-10T08:11:16.821015+00:00", "updated_at": "2026-09-30T13:29:25.251615+00:00"}, {"id": "gpt-5-nano", "label": "GPT-5 nano（最安）", "description": "候補の中で最も安い。5.4 nano より前の世代なので品質は落ちる。コストを最優先する場面向け。", "token_param": "max_completion_tokens", "supports_temperature": false, "reasoning_efforts": ["minimal", "low", "medium", "high"], "reasoning_headroom_tokens": 4000, "price_input_per_mtok": 0.05, "price_output_per_mtok": 0.4, "is_selectable": true, "sort_order": 40, "provider": "openai", "created_at": "2026-09-10T08:11:16.821015+00:00", "updated_at": "2026-09-10T08:11:16.821015+00:00"}, {"id": "gpt-5.6-luna", "label": "GPT-5.6 Luna", "description": "5.6 世代の軽量モデル。価格は 5.4 nano とほぼ同じ。推論を切れば速いが、既定のままだと考えてから答えるぶん待ちが伸びる。", "token_param": "max_completion_tokens", "supports_temperature": true, "reasoning_efforts": ["none", "low", "medium", "high", "xhigh", "max"], "reasoning_headroom_tokens": 6000, "price_input_per_mtok": 0.2, "price_output_per_mtok": 1.2, "is_selectable": true, "sort_order": 50, "provider": "openai", "created_at": "2026-09-10T08:11:16.821015+00:00", "updated_at": "2026-09-10T08:11:16.821015+00:00"}, {"id": "gpt-6-luna", "label": "GPT-6 Luna", "description": "6 世代の軽量モデル（5.6 Luna の後継）。候補の中で 5 nano の次に安く、推論なしなら最初の文字が出るのが速い。深さを上げると考えてから答えるぶん待ちが伸びる。", "token_param": "max_completion_tokens", "supports_temperature": false, "reasoning_efforts": ["none", "low", "medium", "high", "xhigh", "max"], "reasoning_headroom_tokens": 6000, "price_input_per_mtok": 0.1, "price_output_per_mtok": 0.5, "is_selectable": true, "sort_order": 60, "provider": "openai", "created_at": "2026-09-30T13:29:25.563538+00:00", "updated_at": "2026-09-30T13:29:25.563538+00:00"}, {"id": "claude-haiku-5-5", "label": "Claude Haiku 5.5", "description": "Anthropic の軽量モデル（ANTHROPIC_API_KEY が必要）。価格は GPT-6 Luna と同じ水準。temperature は送らず、考え込まずに答える設定で呼ぶ。キーが無い・拒否されたときは既定のモデルに切り替わる。", "token_param": "max_tokens", "supports_temperature": false, "reasoning_efforts": [], "reasoning_headroom_tokens": 0, "price_input_per_mtok": 0.1, "price_output_per_mtok": 0.5, "is_selectable": true, "sort_order": 70, "provider": "anthropic", "created_at": "2026-10-09T16:47:56.906966+00:00", "updated_at": "2026-10-09T16:47:56.906966+00:00"}]$json$) ON CONFLICT DO NOTHING;
INSERT INTO public.ai_use_cases SELECT * FROM json_populate_recordset(NULL::public.ai_use_cases, $json$[{"key": "consult", "label": "AI相談（にちよさん）", "description": "相談ページとマップのミニチャット。土佐弁の会話を1文字ずつ流しながら返すので、待ち時間がそのまま体験に出る。", "model_id": "gpt-6-luna", "reasoning_effort": null, "is_enabled": true, "sort_order": 10, "created_at": "2026-09-10T08:11:16.821015+00:00", "updated_at": "2026-09-30T14:52:38.54208+00:00"}, {"key": "shopChat", "label": "店舗ページのチャット", "description": "店舗詳細ページの短い質問応答。280文字程度の短い返事を速く返す。", "model_id": "gpt-6-luna", "reasoning_effort": null, "is_enabled": true, "sort_order": 20, "created_at": "2026-09-10T08:11:16.821015+00:00", "updated_at": "2026-09-30T14:52:38.608292+00:00"}, {"key": "itinerary", "label": "回り方プラン", "description": "時間と興味から順路を組み立てる。実際に順序を考える処理なので、ここだけは賢いモデルが効く可能性がある。", "model_id": "gpt-6-luna", "reasoning_effort": null, "is_enabled": true, "sort_order": 30, "created_at": "2026-09-10T08:11:16.821015+00:00", "updated_at": "2026-09-30T14:52:38.677348+00:00"}, {"key": "mapAgent", "label": "マップAIアシスタント", "description": "質問から意図を読み取ってJSONで返す。分類・抽出に近い処理。", "model_id": "gpt-5.4-nano", "reasoning_effort": null, "is_enabled": true, "sort_order": 40, "created_at": "2026-09-10T08:11:16.821015+00:00", "updated_at": "2026-09-12T08:36:10.893851+00:00"}, {"key": "vendorHelp", "label": "出店者の相談（にちよさん）", "description": "出店者トップで、出店者がアプリの使い方を聞くヘルプデスク。よくある質問とその店の登録内容を元に、200文字程度で答える。", "model_id": "gpt-6-luna", "reasoning_effort": null, "is_enabled": true, "sort_order": 50, "created_at": "2026-10-01T06:10:20.685387+00:00", "updated_at": "2026-10-02T13:33:33.448845+00:00"}, {"key": "translation", "label": "店舗情報の翻訳", "description": "出店者が入れた店名・ひとこと・商品名などを、外国人来訪者向けに訳す（保存した訳を画面に出す）。短い文を正確に訳す処理なので、軽いモデルで足りる。", "model_id": null, "reasoning_effort": null, "is_enabled": true, "sort_order": 60, "created_at": "2026-10-28T11:58:37.918782+00:00", "updated_at": "2026-10-28T11:58:37.918782+00:00"}]$json$) ON CONFLICT DO NOTHING;
INSERT INTO public.ai_conversation_settings SELECT * FROM json_populate_recordset(NULL::public.ai_conversation_settings, $json$[{"key": "consult.max_turns", "value": 1, "min_value": 1, "max_value": 3, "updated_at": "2026-09-10T08:11:17.851477+00:00"}, {"key": "consult.max_output_tokens", "value": 500, "min_value": 300, "max_value": 1200, "updated_at": "2026-09-10T08:11:17.851477+00:00"}, {"key": "consult.history_limit", "value": 6, "min_value": 0, "max_value": 12, "updated_at": "2026-09-10T08:11:17.851477+00:00"}]$json$) ON CONFLICT DO NOTHING;
